package com.nexbank.auth.dto;
import jakarta.validation.constraints.*;import java.util.UUID;
public final class AuthDtos {private AuthDtos(){} public record Credentials(@Email @NotBlank String email,@NotBlank @Size(min=10,max=72) String password){} public record RefreshRequest(@NotBlank String refreshToken){} public record LogoutRequest(@NotBlank String refreshToken){} public record StaffUserRequest(@Email @NotBlank String email,@NotBlank @Size(min=10,max=72) String password,@NotNull com.nexbank.auth.entity.UserRole role){} public record RoleChangeRequest(@NotNull com.nexbank.auth.entity.UserRole role){} public record UserView(UUID userId,String email,String role){} public record TokenResponse(String accessToken,String refreshToken,String tokenType,UUID userId,String role,long expiresInSeconds){} }
